use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let arr = input.as_array().unwrap();
    let left = &arr[0].as_array().unwrap();
    let right = &arr[1].as_array().unwrap();

    let mut result = Vec::new();
    let mut left_iter = left.iter().peekable();
    let mut right_iter = right.iter().peekable();

    while let (Some(left_item), Some(right_item)) = (left_iter.peek(), right_iter.peek()) {
        let left_key = left_item[0].as_i64().unwrap();
        let right_key = right_item[0].as_i64().unwrap();

        if left_key < right_key {
            left_iter.next();
        } else if left_key > right_key {
            right_iter.next();
        } else {
            result.push(json!([left_key, left_item[1].clone(), right_item[1].clone()]));
            left_iter.next();
            right_iter.next();
        }
    }

    json!(result)
}
